+    ctx.beginPath(); ctx.arc(t.x,t.y,4,0,Math.PI*2); ctx.fill(); ctx.restore();
+  }
+
+  // courier
+  const blink = player.inv>0 && (performance.now()/120|0)%2===0;
+  ctx.save();
+  ctx.translate(player.x,player.y); ctx.rotate(player.angle);
+  ctx.shadowColor='#00f0ff'; ctx.shadowBlur= blink?4:22;
+  ctx.globalAlpha= blink? .45 : 1;
+  ctx.fillStyle='#062a30'; ctx.strokeStyle='#00f0ff'; ctx.lineWidth=2.5;
+  ctx.beginPath(); ctx.moveTo(14,0); ctx.lineTo(-10,-10); ctx.lineTo(-5,0); ctx.lineTo(-10,10); ctx.closePath();
