+  ctx.fillStyle='#fff'; ctx.shadowBlur=8;
+  ctx.beginPath(); ctx.arc(2,0,3.4,0,Math.PI*2); ctx.fill();
+  ctx.restore();
+  // shield ring
+  if(player.inv>0){
+    ctx.save(); ctx.strokeStyle='#00f0ff'; ctx.globalAlpha=.6; ctx.setLineDash([6,6]);
