+}
+el('startBtn').addEventListener('click', startGame);
+el('playBtn').addEventListener('click', ()=>{
+  if(G.mode==='pause'){ togglePause(); } else startGame();
+});
+el('pauseBtn').addEventListener('click', togglePause);
+
+// init
+resetGame(); G.mode='menu';
+showOverlay('NEON PARCEL PANIC',
+  `Steer with <kbd>WASD</kbd> / <kbd>arrows</kbd>. Pick up a glowing parcel, deliver it to the drop zone of the <b>same color</b>. Avoid red patrol drones. You have <b>90 seconds</b> and <b>3 lives</b>. Each delivery: <b>+100</b> and <b>+5s</b>.`);
