cat > /tmp/opencode/shots.py << 'PY'
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
    b = p.chromium.launch(executable_path="/usr/bin/chromium", args=["--no-sandbox"])
    pg = b.new_page(viewport={"width":1000,"height":760})
    pg.goto("http://localhost:8765/index.html?play=1")
    pg.wait_for_timeout(1200)
    # drive right to make trail visible
    pg.keyboard.down("d"); pg.wait_for_timeout(900); pg.keyboard.up("d")
    pg.keyboard.down("s"); pg.wait_for_timeout(300); pg.keyboard.up("s")
    pg.screenshot(path="/tmp/opencode/final-gameplay.png")
    # delivery moment: pickup then deliver, screenshot fast
    pg.evaluate("""()=>{
      const {G, player} = window.__NPP;
      const p = G.parcels.find(p=>p.color==='MAGENTA') || G.parcels[0];
      player.x=p.x; player.y=p.y; player.vx=0; player.vy=0;
    }""")
    pg.wait_for_timeout(400)
    pg.evaluate("""()=>{
      const {G, player} = window.__NPP;
      const zones=[{"color":"MAGENTA","x":100,"y":560,"w":110,"h":26},{"color":"YELLOW","x":425,"y":560,"w":110,"h":26},{"color":"LIME","x":750,"y":560,"w":110,"h":26}];
      const z=zones.find(z=>z.color===G.carry);
      player.x=z.x+z.w/2; player.y=z.y-12; player.vx=0; player.vy=0;
    }""")
    pg.wait_for_timeout(250)
    pg.screenshot(path="/tmp/opencode/final-delivery.png")
    print("score", pg.evaluate("window.__NPP.G.score"), "delivered", pg.evaluate("window.__NPP.G.delivered"))
    # menu shot fresh
    pg.goto("http://localhost:8765/index.html")
    pg.wait_for_timeout(800)
    pg.screenshot(path="/tmp/opencode/final-menu.png")
    b.close()
print("shots done")
PY
